<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./matrixmedia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --phone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 13800138000</span></span>
